import React, { useState, useRef, useEffect } from 'react';
import axios from 'axios';

const TypingIndicator = () => (
    <div className="flex items-end gap-2 mb-3">
        <div className="w-6 h-6 rounded-full bg-gradient-to-br from-[#10221c] to-emerald-600 flex items-center justify-center flex-shrink-0">
            <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="white" className="w-3 h-3">
                <path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm-2 14.5v-9l6 4.5-6 4.5z"/>
            </svg>
        </div>
        <div className="bg-[#f0f0f0] rounded-2xl rounded-bl-sm px-4 py-3 flex gap-1 items-center">
            <span className="w-1.5 h-1.5 bg-slate-400 rounded-full animate-bounce" style={{ animationDelay: '0ms' }}></span>
            <span className="w-1.5 h-1.5 bg-slate-400 rounded-full animate-bounce" style={{ animationDelay: '150ms' }}></span>
            <span className="w-1.5 h-1.5 bg-slate-400 rounded-full animate-bounce" style={{ animationDelay: '300ms' }}></span>
        </div>
    </div>
);

const AIChatWidget = () => {
    const [isOpen, setIsOpen] = useState(false);
    const [messages, setMessages] = useState([
        { role: 'model', text: "Hello! I'm **Bindass AI** — your personal style consultant. ✨\n\nHow can I help you today? I can assist with product recommendations, size guides, collections, or anything about our brand!" }
    ]);
    const [input, setInput] = useState('');
    const [isLoading, setIsLoading] = useState(false);
    const [isAnimating, setIsAnimating] = useState(false);
    const messagesEndRef = useRef(null);
    const inputRef = useRef(null);

    useEffect(() => {
        if (messagesEndRef.current) {
            messagesEndRef.current.scrollIntoView({ behavior: 'smooth' });
        }
    }, [messages, isLoading]);

    useEffect(() => {
        if (isOpen && inputRef.current) {
            setTimeout(() => inputRef.current?.focus(), 350);
        }
    }, [isOpen]);

    const toggleChat = () => {
        setIsAnimating(true);
        setIsOpen(prev => !prev);
        setTimeout(() => setIsAnimating(false), 400);
    };

    const renderText = (text) => {
        // Simple markdown: bold
        return text
            .replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>')
            .replace(/\n/g, '<br/>');
    };

    const sendMessage = async () => {
        const trimmed = input.trim();
        if (!trimmed || isLoading) return;

        const userMsg = { role: 'user', text: trimmed };
        const newMessages = [...messages, userMsg];
        setMessages(newMessages);
        setInput('');
        setIsLoading(true);

        try {
            // Build history (exclude the initial greeting system message)
            const history = newMessages.slice(1, -1).map(m => ({
                role: m.role,
                text: m.text
            }));

            const { data } = await axios.post('http://localhost:5001/api/ai/chat', {
                message: trimmed,
                history
            });

            setMessages(prev => [...prev, { role: 'model', text: data.reply }]);
        } catch (error) {
            setMessages(prev => [...prev, {
                role: 'model',
                text: "I'm having a moment of connection issues. Please try again shortly!"
            }]);
        } finally {
            setIsLoading(false);
        }
    };

    const handleKeyDown = (e) => {
        if (e.key === 'Enter' && !e.shiftKey) {
            e.preventDefault();
            sendMessage();
        }
    };

    return (
        <>
            {/* Chat Dialog */}
            <div
                className={`fixed bottom-20 right-0 left-0 mx-2 sm:mx-0 sm:right-6 sm:left-auto z-[200] w-auto sm:w-[360px] max-h-[70vh] sm:max-h-[520px] flex flex-col bg-white rounded-2xl shadow-2xl border border-gray-100 overflow-hidden transition-all duration-400 origin-bottom sm:origin-bottom-right ${
                    isOpen
                        ? 'opacity-100 scale-100 translate-y-0 pointer-events-auto'
                        : 'opacity-0 scale-90 translate-y-4 pointer-events-none'
                }`}
                style={{ transition: 'opacity 0.35s ease, transform 0.35s cubic-bezier(0.34, 1.56, 0.64, 1)' }}
            >
                {/* Header */}
                <div className="bg-gradient-to-r from-[#10221c] to-[#1a3d32] px-5 py-4 flex items-center justify-between flex-shrink-0">
                    <div className="flex items-center gap-3">
                        <div className="w-8 h-8 rounded-full bg-white/10 backdrop-blur flex items-center justify-center border border-white/20">
                            <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="white" strokeWidth="1.5" className="w-4 h-4">
                                <path strokeLinecap="round" strokeLinejoin="round" d="M9.813 15.904L9 18.75l-.813-2.846a4.5 4.5 0 00-3.09-3.09L2.25 12l2.846-.813a4.5 4.5 0 003.09-3.09L9 5.25l.813 2.846a4.5 4.5 0 003.09 3.09L15.75 12l-2.846.813a4.5 4.5 0 00-3.09 3.09z" />
                                <path strokeLinecap="round" strokeLinejoin="round" d="M18.259 8.715L18 9.75l-.259-1.035a3.375 3.375 0 00-2.455-2.456L14.25 6l1.036-.259a3.375 3.375 0 002.455-2.456L18 2.25l.259 1.035a3.375 3.375 0 002.456 2.456L21.75 6l-1.035.259a3.375 3.375 0 00-2.456 2.456z" />
                            </svg>
                        </div>
                        <div>
                            <p className="text-white font-bold text-sm tracking-wide">Bindass AI</p>
                            <p className="text-emerald-300 text-[10px] font-medium uppercase tracking-widest">Style Consultant</p>
                        </div>
                    </div>
                    <button
                        onClick={toggleChat}
                        className="w-7 h-7 rounded-full bg-white/10 hover:bg-white/20 flex items-center justify-center transition-colors"
                    >
                        <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="white" className="w-4 h-4">
                            <path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" />
                        </svg>
                    </button>
                </div>

                {/* Messages */}
                <div className="flex-1 overflow-y-auto px-4 py-4 space-y-1 bg-[#fafafa]" style={{ maxHeight: '360px', scrollbarWidth: 'none' }}>
                    {messages.map((msg, i) => (
                        <div key={i} className={`flex items-end gap-2 mb-3 ${msg.role === 'user' ? 'flex-row-reverse' : 'flex-row'}`}>
                            {msg.role === 'model' && (
                                <div className="w-6 h-6 rounded-full bg-gradient-to-br from-[#10221c] to-emerald-600 flex items-center justify-center flex-shrink-0">
                                    <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="white" strokeWidth="2" className="w-3 h-3">
                                        <path strokeLinecap="round" strokeLinejoin="round" d="M9.813 15.904L9 18.75l-.813-2.846a4.5 4.5 0 00-3.09-3.09L2.25 12l2.846-.813a4.5 4.5 0 003.09-3.09L9 5.25l.813 2.846a4.5 4.5 0 003.09 3.09L15.75 12l-2.846.813a4.5 4.5 0 00-3.09 3.09z" />
                                    </svg>
                                </div>
                            )}
                            <div
                                className={`max-w-[78%] px-4 py-2.5 rounded-2xl text-[13px] leading-relaxed ${
                                    msg.role === 'user'
                                        ? 'bg-[#10221c] text-white rounded-br-sm'
                                        : 'bg-white text-slate-800 rounded-bl-sm shadow-sm border border-gray-100'
                                }`}
                                dangerouslySetInnerHTML={{ __html: renderText(msg.text) }}
                            />
                        </div>
                    ))}
                    {isLoading && <TypingIndicator />}
                    <div ref={messagesEndRef} />
                </div>

                {/* Input Area */}
                <div className="px-4 py-3 border-t border-gray-100 bg-white flex-shrink-0">
                    <div className="flex items-center gap-2 bg-[#f5f5f5] rounded-xl px-3 py-2">
                        <input
                            ref={inputRef}
                            type="text"
                            value={input}
                            onChange={(e) => setInput(e.target.value)}
                            onKeyDown={handleKeyDown}
                            placeholder="Ask about our collection..."
                            className="flex-1 bg-transparent text-sm text-slate-800 placeholder-slate-400 outline-none font-['Manrope']"
                        />
                        <button
                            onClick={sendMessage}
                            disabled={!input.trim() || isLoading}
                            className={`w-8 h-8 rounded-lg flex items-center justify-center transition-all flex-shrink-0 ${
                                input.trim() && !isLoading
                                    ? 'bg-[#10221c] hover:bg-emerald-900 active:scale-90'
                                    : 'bg-slate-200 cursor-not-allowed'
                            }`}
                        >
                            <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="white" className="w-4 h-4">
                                <path strokeLinecap="round" strokeLinejoin="round" d="M6 12L3.269 3.126A59.768 59.768 0 0121.485 12 59.77 59.77 0 013.27 20.876L5.999 12zm0 0h7.5" />
                            </svg>
                        </button>
                    </div>
                    <p className="text-center text-[9px] text-slate-300 uppercase tracking-widest mt-1.5 font-medium">Powered by Gemini AI</p>
                </div>
            </div>

            {/* Floating Trigger Button */}
            <button
                onClick={toggleChat}
                className={`fixed bottom-6 right-6 z-[200] w-14 h-14 rounded-full shadow-xl flex items-center justify-center transition-all duration-300 group ${
                    isOpen
                        ? 'bg-slate-700 rotate-[360deg]'
                        : 'bg-gradient-to-br from-[#10221c] to-emerald-700 hover:scale-110 hover:shadow-emerald-900/40 hover:shadow-2xl'
                }`}
                aria-label="Open AI Chat"
            >
                {isOpen ? (
                    <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="white" className="w-5 h-5">
                        <path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" />
                    </svg>
                ) : (
                    <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="white" strokeWidth="1.5" className="w-6 h-6">
                        <path strokeLinecap="round" strokeLinejoin="round" d="M9.813 15.904L9 18.75l-.813-2.846a4.5 4.5 0 00-3.09-3.09L2.25 12l2.846-.813a4.5 4.5 0 003.09-3.09L9 5.25l.813 2.846a4.5 4.5 0 003.09 3.09L15.75 12l-2.846.813a4.5 4.5 0 00-3.09 3.09z" />
                        <path strokeLinecap="round" strokeLinejoin="round" d="M18.259 8.715L18 9.75l-.259-1.035a3.375 3.375 0 00-2.455-2.456L14.25 6l1.036-.259a3.375 3.375 0 002.455-2.456L18 2.25l.259 1.035a3.375 3.375 0 002.456 2.456L21.75 6l-1.035.259a3.375 3.375 0 00-2.456 2.456z" />
                    </svg>
                )}
                {/* Pulse ring */}
                {!isOpen && (
                    <span className="absolute inset-0 rounded-full animate-ping bg-emerald-600 opacity-20"></span>
                )}
            </button>
        </>
    );
};

export default AIChatWidget;
